def apply(inputs, premises):
    question = inputs["current_question"]
    clauses = premises["nondisclosure_clauses"]
    definitions = premises["party_and_recipient_definitions"]
    role_supported = False
    for definition in definitions:
        if "Receiving Party" in definition or "Party" in definition or "Volunteer" in definition:
            role_supported = True
    employees_permitted = False
    advisors_permitted = False
    confidentiality_required = False
    need_to_know_required = False
    purpose_limited = False
    for clause in clauses:
        if "Receiving Party" in clause or "each Party" in clause or "Each Party" in clause or "Volunteer" in clause:
            role_supported = True
        permission_clause = "may disclose" in clause and "Confidential Information" in clause
        if permission_clause:
            if "employees" in clause:
                employees_permitted = True
            if "legal advisors" in clause or "financial advisors" in clause or "accountants" in clause:
                advisors_permitted = True
            if "confidentiality" in clause or "confidential" in clause:
                confidentiality_required = True
            if "need to know" in clause or "bona fide need to know" in clause:
                need_to_know_required = True
            if "Business Purpose" in clause or "the Purpose" in clause or "for the Purpose" in clause:
                purpose_limited = True
    employee_query = "Receiving Party's employees" in question
    advisor_query = "professional advisors" in question
    class_permitted = False
    if employee_query and employees_permitted:
        class_permitted = True
    if advisor_query and advisors_permitted:
        class_permitted = True
    exception_applies = role_supported and class_permitted and confidentiality_required and need_to_know_required and purpose_limited
    return {"exception_applies": exception_applies}

def apply(inputs, premises):
    question = inputs["current_question"]
    clauses = premises["nondisclosure_clauses"]
    definitions = premises["party_and_recipient_definitions"]
    receiving_party_role = False
    for definition in definitions:
        if "Receiving Party" in definition:
            receiving_party_role = True
    general_third_party_prohibition = False
    employee_specific_prohibition = False
    for clause in clauses:
        if "Receiving Party" in clause:
            receiving_party_role = True
        prohibition_clause = "not to disclose" in clause or "shall not disclose" in clause or ("agrees not to" in clause and "divulge" in clause)
        if prohibition_clause and "third part" in clause:
            general_third_party_prohibition = True
        if prohibition_clause and "employees" in clause:
            employee_specific_prohibition = True
    disclosure_query = "Receiving Party" in question and "may share some Confidential Information" in question
    employee_query = "Receiving Party's employees" in question
    third_party_query = "third-parties" in question or "third parties" in question
    if not disclosure_query:
        answer = "NotMentioned"
    elif inputs["representative_exception_applies"]:
        answer = "Entailment"
    elif third_party_query and general_third_party_prohibition:
        answer = "Contradiction"
    elif employee_query and receiving_party_role and employee_specific_prohibition:
        answer = "Contradiction"
    else:
        answer = "NotMentioned"
    return {"answer": answer}
